import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

ReactDOM.createRoot(document.getElementById('root')!).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useEffect, useState } from 'react';

const Scenarios: React.FC = () => {
  const [scenarioId, setScenarioId] = useState('');
  const [fileContent, setFileContent] = useState('');
  const [uploading, setUploading] = useState(false);
  const [uploadError, setUploadError] = useState<string | null>(null);
  const [scenarioList, setScenarioList] = useState<string[]>([]);

  const fetchScenarios = async () => {
    try {
      const res = await fetch('/scenarios/list');
      if (!res.ok) throw new Error('Failed to fetch scenarios');
      const data = await res.json();
      setScenarioList(Array.isArray(data) ? data : []);
    } catch (e) {
      setScenarioList([]);
    }
  };

  useEffect(() => {
    fetchScenarios();
  }, []);

  const onFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setUploadError(null);
    const file = e.target.files && e.target.files[0];
    if (!file) {
      setFileContent('');
      return;
    }
    const reader = new FileReader();
    reader.onload = () => {
      if (typeof reader.result === 'string') {
        setFileContent(reader.result);
      } else {
        setFileContent('');
      }
    };
    reader.readAsText(file);
  };

  const onUpload = async (e: React.FormEvent) => {
    e.preventDefault();
    setUploadError(null);
    if (!scenarioId.match(/^[\w\-]+$/)) {
      setUploadError('Scenario ID must contain only letters, digits, underscores or dashes');
      return;
    }
    if (!fileContent) {
      setUploadError('No file content to upload');
      return;
    }
    setUploading(true);
    try {
      const res = await fetch('/scenarios/upload', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ scenarioId, jsonl: fileContent })
      });
      if (!res.ok) {
        throw new Error(`Upload failed: ${res.statusText}`);
      }
      await fetchScenarios();
      setScenarioId('');
      setFileContent('');
    } catch (err: any) {
      setUploadError(err.message || 'Upload failed');
    } finally {
      setUploading(false);
    }
  };

  return (
    <div>
      <h2>Scenarios</h2>
      <form onSubmit={onUpload}>
        <label htmlFor="scenarioId">Scenario ID:</label>
        <input
          id="scenarioId"
          type="text"
          value={scenarioId}
          onChange={e => setScenarioId(e.target.value)}
          placeholder="letters, digits, underscore, dash"
          required
          disabled={uploading}
        />

        <label htmlFor="scenarioFile">Scenario File (JSONL):</label>
        <input
          id="scenarioFile"
          type="file"
          accept="text/plain,application/jsonl"
          onChange={onFileChange}
          disabled={uploading}
          required
        />

        <button type="submit" disabled={uploading}>Upload</button>

        {uploadError && <div className="error-message">{uploadError}</div>}
      </form>

      <h3>Available Scenarios</h3>
      {scenarioList.length === 0 ? (
        <p>No scenarios found.</p>
      ) : (
        <ul>
          {scenarioList.map(id => (
            <li key={id}>{id}</li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default Scenarios;

import React, { useState } from 'react';

const StartReplay: React.FC = () => {
  const [scenarioId, setScenarioId] = useState('');
  const [targetBaseUrl, setTargetBaseUrl] = useState('');
  const [rps, setRps] = useState(10);
  const [durationSec, setDurationSec] = useState(60);
  const [mode, setMode] = useState<'burst' | 'timestamp'>('burst');
  const [speed, setSpeed] = useState(1.0);
  const [maxDelayMs, setMaxDelayMs] = useState(0);
  const [startFromTs, setStartFromTs] = useState('');
  const [endAtTs, setEndAtTs] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [runId, setRunId] = useState<string | null>(null);

  const onSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setRunId(null);

    if (!scenarioId.match(/^[\w\-]+$/)) {
      setError('Scenario ID must contain only letters, digits, underscores or dashes');
      return;
    }
    if (!targetBaseUrl) {
      setError('Target Base URL is required');
      return;
    }
    if (rps <= 0) {
      setError('RPS must be positive');
      return;
    }
    if (durationSec <= 0) {
      setError('Duration must be positive');
      return;
    }
    if (speed <= 0) {
      setError('Speed must be positive');
      return;
    }
    // Validate timestamps if mode=timestamp
    if (mode === 'timestamp') {
      if (startFromTs && isNaN(Date.parse(startFromTs))) {
        setError('Start From Timestamp is invalid');
        return;
      }
      if (endAtTs && isNaN(Date.parse(endAtTs))) {
        setError('End At Timestamp is invalid');
        return;
      }
    }

    const payload: any = {
      scenarioId,
      targetBaseUrl,
      rps,
      durationSec,
      mode,
      speed,
      maxDelayMs
    };
    if (mode === 'timestamp') {
      if (startFromTs) payload.startFromTs = startFromTs;
      if (endAtTs) payload.endAtTs = endAtTs;
    }

    setLoading(true);

    try {
      const res = await fetch('/replay/start', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      if (!res.ok) {
        let errText = await res.text();
        setError(`Failed to start replay: ${res.statusText} ${errText}`);
        setLoading(false);
        return;
      }
      const data = await res.json();
      if (data.runId) {
        setRunId(data.runId);
      } else {
        setError('No runId returned');
      }
    } catch (e: any) {
      setError(e.message || 'Failed to start replay');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      <h2>Start Replay</h2>
      <form onSubmit={onSubmit}>
        <label htmlFor="scenarioId">Scenario ID:</label>
        <input
          id="scenarioId"
          type="text"
          value={scenarioId}
          onChange={e => setScenarioId(e.target.value)}
          required
          disabled={loading}
        />

        <label htmlFor="targetBaseUrl">Target Base URL:</label>
        <input
          id="targetBaseUrl"
          type="url"
          value={targetBaseUrl}
          onChange={e => setTargetBaseUrl(e.target.value)}
          placeholder="http://..."
          required
          disabled={loading}
        />

        <label htmlFor="rps">Requests Per Second (RPS):</label>
        <input
          id="rps"
          type="number"
          min={1}
          value={rps}
          onChange={e => setRps(Number(e.target.value))}
          required
          disabled={loading}
        />

        <label htmlFor="durationSec">Duration (seconds):</label>
        <input
          id="durationSec"
          type="number"
          min={1}
          value={durationSec}
          onChange={e => setDurationSec(Number(e.target.value))}
          required
          disabled={loading}
        />

        <label htmlFor="mode">Replay Mode:</label>
        <select
          id="mode"
          value={mode}
          onChange={e => setMode(e.target.value as 'burst' | 'timestamp')}
          disabled={loading}
        >
          <option value="burst">burst</option>
          <option value="timestamp">timestamp</option>
        </select>

        <label htmlFor="speed">Speed (multiplier, only timestamp mode):</label>
        <input
          id="speed"
          type="number"
          min={0.01}
          step={0.01}
          value={speed}
          onChange={e => setSpeed(Number(e.target.value))}
          disabled={loading || mode !== 'timestamp'}
        />

        <label htmlFor="maxDelayMs">Max Delay (ms, only timestamp mode):</label>
        <input
          id="maxDelayMs"
          type="number"
          min={0}
          value={maxDelayMs}
          onChange={e => setMaxDelayMs(Number(e.target.value))}
          disabled={loading || mode !== 'timestamp'}
        />

        <label htmlFor="startFromTs">Start From Timestamp (RFC3339, optional):</label>
        <input
          id="startFromTs"
          type="datetime-local"
          value={startFromTs}
          onChange={e => setStartFromTs(e.target.value)}
          disabled={loading || mode !== 'timestamp'}
        />

        <label htmlFor="endAtTs">End At Timestamp (RFC3339, optional):</label>
        <input
          id="endAtTs"
          type="datetime-local"
          value={endAtTs}
          onChange={e => setEndAtTs(e.target.value)}
          disabled={loading || mode !== 'timestamp'}
        />

        <button type="submit" disabled={loading}>Start Replay</button>
      </form>

      {loading && <div className="loading-spinner" aria-label="Loading"></div>}

      {error && <div className="error-message">{error}</div>}

      {runId && (
        <div>
          <p>Replay started! Run ID: <strong>{runId}</strong></p>
          <p>
            View report: <a href={`/replay/report?runId=${encodeURIComponent(runId)}`} target="_blank" rel="noreferrer">Report</a>
          </p>
        </div>
      )}
    </div>
  );
};

export default StartReplay;

import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';

interface Run {
  runId: string;
  state: string;
  startedAt: string;
  finishedAt?: string;
  stats: {
    requests: number;
    errors: number;
    p95ms: number;
  };
}

const Runs: React.FC = () => {
  const [runs, setRuns] = useState<Run[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const navigate = useNavigate();

  const fetchRuns = async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch('/replay/runs?limit=20');
      if (!res.ok) throw new Error('Failed to fetch runs');
      const data = await res.json();
      if (Array.isArray(data)) {
        setRuns(data);
      } else {
        setRuns([]);
      }
    } catch (e: any) {
      setError(e.message || 'Error fetching runs');
      setRuns([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRuns();
  }, []);

  const openReport = (runId: string) => {
    navigate(`/replay/report?runId=${encodeURIComponent(runId)}`);
  };

  return (
    <div>
      <h2>Replay Runs</h2>
      {loading && <div className="loading-spinner" aria-label="Loading"></div>}
      {error && <div className="error-message">{error}</div>}
      {!loading && runs.length === 0 && <p>No runs found.</p>}
      {!loading && runs.length > 0 && (
        <table className="table">
          <thead>
            <tr>
              <th>Run ID</th>
              <th>State</th>
              <th>Started At</th>
              <th>Finished At</th>
              <th>Requests</th>
              <th>Errors</th>
              <th>P95 Latency (ms)</th>
              <th>Report</th>
            </tr>
          </thead>
          <tbody>
            {runs.map(run => (
              <tr key={run.runId}>
                <td>{run.runId}</td>
                <td>{run.state}</td>
                <td>{new Date(run.startedAt).toLocaleString()}</td>
                <td>{run.finishedAt ? new Date(run.finishedAt).toLocaleString() : '-'}</td>
                <td>{run.stats.requests}</td>
                <td>{run.stats.errors}</td>
                <td>{run.stats.p95ms}</td>
                <td>
                  <button className="link-button" onClick={() => openReport(run.runId)}>View</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
};

export default Runs;

import React, { useEffect, useState } from 'react';
import { useLocation } from 'react-router-dom';

const RunReport: React.FC = () => {
  const location = useLocation();
  const [runId, setRunId] = useState<string | null>(null);
  const [report, setReport] = useState<any>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const params = new URLSearchParams(location.search);
    const id = params.get('runId');
    setRunId(id);
  }, [location.search]);

  useEffect(() => {
    if (!runId) return;
    setLoading(true);
    setError(null);
    setReport(null);

    fetch(`/replay/report?runId=${encodeURIComponent(runId)}`)
      .then(res => {
        if (!res.ok) throw new Error(`Failed to load report: ${res.statusText}`);
        return res.json();
      })
      .then(data => {
        setReport(data);
      })
      .catch(e => setError(e.message || 'Failed to fetch report'))
      .finally(() => setLoading(false));
  }, [runId]);

  if (!runId) {
    return <div><p>No runId specified in URL.</p></div>;
  }

  return (
    <div>
      <h2>Run Report - {runId}</h2>
      {loading && <div className="loading-spinner" aria-label="Loading"></div>}
      {error && <div className="error-message">{error}</div>}
      {report && (
        <pre style={{whiteSpace: 'pre-wrap', wordBreak: 'break-word'}}>
          {JSON.stringify(report, null, 2)}
        </pre>
      )}
    </div>
  );
};

export default RunReport;
